import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { externalDataDestinationsList } from 'products/warehouse_sources/frontend/generated/api'
import { ExternalDataDestinationApi } from 'products/warehouse_sources/frontend/generated/api.schemas'

import { sourceWizardLogic } from '../sourceWizardLogic'
import { defaultDestinationIds, toggleDestinationId } from './destinationStepUtils'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface destinationStepLogicValues {
    wizardDestinationIds: string[] // sourceWizardLogic
    currentTeamId: number | null // teamLogic
    destinations: ExternalDataDestinationApi[]
    destinationsLoading: boolean
    hasLoaded: boolean
    selectedIds: string[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface destinationStepLogicActions {
    setWizardDestinationIds: (destinationIds: string[]) => {
        destinationIds: string[]
    } // sourceWizardLogic
    loadDestinations: () => any
    loadDestinationsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadDestinationsSuccess: (
        destinations: ExternalDataDestinationApi[],
        payload?: any
    ) => {
        destinations: ExternalDataDestinationApi[]
        payload?: any
    }
    selectDefault: () => {
        value: true
    }
    toggleDestination: (destinationId: string) => {
        destinationId: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface destinationStepLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        selectedIds: (wizardDestinationIds: any) => string[]
    }
}

export type destinationStepLogicType = MakeLogicType<
    destinationStepLogicValues,
    destinationStepLogicActions,
    Record<string, any>,
    destinationStepLogicMeta
>

export const destinationStepLogic = kea<destinationStepLogicType>([
    path(['products', 'data_warehouse', 'frontend', 'scenes', 'NewSourceScene', 'destinationStepLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamId'], sourceWizardLogic, ['wizardDestinationIds']],
        actions: [sourceWizardLogic, ['setWizardDestinationIds']],
    })),
    actions({
        toggleDestination: (destinationId: string) => ({ destinationId }),
        selectDefault: true,
    }),
    loaders(({ values }: any) => ({
        destinations: [
            [] as ExternalDataDestinationApi[],
            {
                loadDestinations: async () => {
                    const response = await externalDataDestinationsList(String(values.currentTeamId))
                    return response.results ?? []
                },
            },
        ],
    })),
    reducers({
        hasLoaded: [
            false,
            {
                loadDestinationsSuccess: () => true,
            },
        ],
    }),
    selectors({
        // The wizard owns the picked set, so it survives stepping back and forth and is still
        // there when the source is created.
        selectedIds: [(s: any) => [s.wizardDestinationIds], (ids: string[]) => ids],
    }),
    listeners(({ values, actions }: any) => ({
        toggleDestination: ({ destinationId }: { destinationId: string }) => {
            actions.setWizardDestinationIds(toggleDestinationId(values.wizardDestinationIds, destinationId))
        },
        selectDefault: () => {
            actions.setWizardDestinationIds(defaultDestinationIds(values.destinations, values.wizardDestinationIds))
        },
    })),
    afterMount(({ actions }: any) => {
        actions.loadDestinations()
    }),
])
